<?php
namespace App\Http\Controllers\Admin;use App\Http\Controllers\Controller;use App\Models\{NavigationItem,NavigationMenu};use Illuminate\Http\Request;
class NavigationController extends Controller{public function index(){return view('admin.navigation.index',['menus'=>NavigationMenu::with('allItems')->orderBy('name')->get()]);}public function storeMenu(Request $r){$d=$r->validate(['name'=>'required|string|max:120','location'=>'required|string|max:80|unique:navigation_menus,location']);NavigationMenu::create($d+['status'=>true]);return back()->with('success','Navigation menu created.');}public function storeItem(Request $r,NavigationMenu $menu){$d=$r->validate(['parent_id'=>'nullable|exists:navigation_items,id','label'=>'required|string|max:120','url'=>['required','string','max:1000','regex:/^(\/|https?:\/\/|#)/i'],'target'=>'required|in:_self,_blank','sort_order'=>'nullable|integer|min:0','status'=>'nullable|boolean']);if(!empty($d['parent_id'])&&!$menu->allItems()->whereKey($d['parent_id'])->exists())return back()->withInput()->with('error','Parent item must belong to the same navigation menu.');$menu->allItems()->create($d+['status'=>$r->boolean('status')]);return back()->with('success','Navigation item added.');}public function destroyItem(NavigationItem $item){$item->delete();return back()->with('success','Navigation item removed.');}}

